import React, { useRef } from "react";
import { useVirtualizer } from "@tanstack/react-virtual";

export function VirtualTransactionList({ transactions }) {
  const parentRef = useRef(null);

  const rowVirtualizer = useVirtualizer({
    count: transactions.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 50,
    overscan: 5,
  });

  return (
    <div ref={parentRef} style={{ height: "400px", overflow: "auto", border: "1px solid #cbd5e1" }}>
      <div style={{ height: `${rowVirtualizer.getTotalSize()}px`, width: "100%", position: "relative" }}>
        {rowVirtualizer.getVirtualItems().map((virtualRow) => {
          const item = transactions[virtualRow.index];
          return (
            <div
              key={virtualRow.key}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                height: `${virtualRow.size}px`,
                transform: `translateY(${virtualRow.start}px)`,
              }}
            >
              Row #{virtualRow.index}: {item.title} — ${item.amount}
            </div>
          );
        })}
      </div>
    </div>
  );
}
```

### 7. Detailed Line-by-Line Explanation
- Line 5: `parentRef` attaches to the scrollable container `<div>` with fixed height (`400px`) and `overflow: auto`.
- Line 7: `useVirtualizer` initializes the virtual calculation engine with total count and estimated row size (`50px`).
- Line 15: An outer spacer `<div>` with height `rowVirtualizer.getTotalSize()` forces the scrollbar to reflect the full length of the dataset.
- Line 16: `rowVirtualizer.getVirtualItems()` returns only the currently visible row instances (plus 5 overscan rows).
- Line 24: Each row is positioned absolutely and translated along the Y-axis via GPU-accelerated CSS `transform: translateY(...)`.

### 8. Under-the-Hood Internal Engine Flow
The virtualizer listens to the scroll container's native `scroll` event (passively). On each frame, it divides `scrollTop` by item height to determine `startIndex` and `endIndex`. React renders only those indexed items, translating them into their exact coordinates.

### 9. When to Use It
Any dataset exceeding 100–200 complex DOM rows: enterprise audit tables, social media feeds, autocomplete search dropdowns with thousands of entries, and log viewers.

### 10. When NOT to Use It
Small lists (<50 items) where standard React array `.map()` overhead is negligible, or documents requiring native browser full-text search (`Ctrl+F`) across unmounted content.

### 11. Common Mistakes & Anti-Patterns
Forgetting to specify fixed height or `overflow: auto` on the parent container, causing `getScrollElement()` to evaluate to `window` or collapse to zero height.

### 12. Performance & Accessibility (A11y) Implications
Screen readers can struggle with virtualized lists if not announced properly. Provide `aria-rowcount={transactions.length}` and `aria-rowindex={virtualRow.index + 1}` on rows to preserve accessibility contexts.

