import DOMPurify from "dompurify";

export function SafeMarkdownViewer({ rawHtmlContent }) {
  // 1. Sanitize untrusted markup to prevent XSS attacks
  const cleanMarkup = DOMPurify.sanitize(rawHtmlContent);

  const headingRef = useRef(null);

  useEffect(() => {
    // 2. Manage focus for screen readers when content loads
    headingRef.current?.focus();

    // 3. Memory leak protection: event listeners MUST have cleanups
    const handleResize = () => console.log("Window resized");
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [rawHtmlContent]);

  return (
    <main role="main" aria-label="Article content">
      <h1 ref={headingRef} tabIndex={-1}>Documentation</h1>
      <article dangerouslySetInnerHTML={{ __html: cleanMarkup }} />
    </main>
  );
}
