import React from "react";

// 1. Generic Table Component Props
interface TableProps<T> {
  items: T[];
  keyExtractor: (item: T) => string | number;
  renderRow: (item: T) => React.ReactNode;
}

export function GenericTable<T>({ items, keyExtractor, renderRow }: TableProps<T>) {
  return (
    <table>
      <tbody>
        {items.map(item => (
          <tr key={keyExtractor(item)}>
            <td>{renderRow(item)}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

// 2. Mutually Exclusive Button vs Link Props (Discriminated Union)
type ButtonComponentProps =
  | ({ as: "button"; onClick: () => void; href?: never } & React.ButtonHTMLAttributes<HTMLButtonElement>)
  | ({ as: "link"; href: string; onClick?: never } & React.AnchorHTMLAttributes<HTMLAnchorElement>);

export function PolymorphicAction(props: ButtonComponentProps) {
  if (props.as === "link") {
    return <a href={props.href}>{props.children}</a>;
  }
  return <button onClick={props.onClick}>{props.children}</button>;
}
```

### 7. Detailed Line-by-Line Explanation
- Line 4: `interface TableProps<T>` accepts a generic type parameter `T` representing each item in the dataset.
- Line 10: `GenericTable<T>` automatically infers `T` from the passed `items` array, providing instant type checking for `renderRow(item)`.
- Line 24: `ButtonComponentProps` uses a discriminated union on `as`. If `as === "link"`, `href` is required and `button` props are disallowed.
- Line 29: TypeScript narrows `props` inside the `if` block, guaranteeing that `props.href` exists safely.

### 8. Under-the-Hood Internal Engine Flow
The TypeScript compiler inspects the discriminant property (e.g. `as`) to narrow the union type in conditional branches. For generics, the compiler performs type argument inference at the call site, locking downstream callback parameters to the inferred type.

### 9. When to Use It
Reusable data tables, virtualized lists, dropdown select components, modal actions, and polymorphic UI components that can render as either `<a>` or `<button>`.

### 10. When NOT to Use It
Simple leaf components with fixed data structures where introducing generics adds unnecessary complexity.

### 11. Common Mistakes & Anti-Patterns
Using optional properties (`href?: string; onClick?: () => void`) instead of discriminated unions, which allows developers to mistakenly pass both or neither.

### 12. Performance & Accessibility (A11y) Implications
Discriminated unions ensure that links always render valid `href` attributes and buttons always have keyboard activation, preventing invalid HTML combinations.

### 13. Real-World Production Usage
Enterprise design systems like Radix UI Primitives and TanStack Table (`@tanstack/react-table`) which are built entirely on TypeScript generics.

### 14. Common Interview Questions & Spoken Answers
**Q: How do you enforce mutually exclusive props in a React TypeScript component?**
**Spoken Answer:** By using a TypeScript Discriminated Union. We define two or more types joined by a union (`|`), each having a common discriminant property (or setting the conflicting prop to `never`). When TypeScript inspects the props, it enforces that only props matching the specific variant are allowed, throwing a compile-time error if conflicting props are passed simultaneously.

