import React from "react";

// Blueprint: Discriminated Union Async Request State
export type AsyncState<T> =
  | { status: "idle"; data: null; error: null }
  | { status: "loading"; data: null; error: null }
  | { status: "success"; data: T; error: null }
  | { status: "error"; data: null; error: Error };

export function UserView({ state }: { state: AsyncState<{ id: string; name: string }> }) {
  switch (state.status) {
    case "idle":
      return <div>Ready to load.</div>;
    case "loading":
      return <div>Loading user details...</div>;
    case "error":
      return <div style={{ color: "red" }}>Error: {state.error.message}</div>;
    case "success":
      // TypeScript knows state.data is guaranteed non-null here!
      return <div>Welcome, {state.data.name}!</div>;
  }
}
```

### 7. Detailed Line-by-Line Explanation
- Line 4: `AsyncState<T>` defines 4 distinct states using `status` as the discriminant key.
- Line 11: In the `switch` statement, TypeScript exhaustively narrows the type in each `case` block.
- Line 17: In the `error` case, `state.error` is guaranteed to be an `Error` object.
- Line 19: In the `success` case, `state.data` is guaranteed to be of type `T` (non-null), eliminating optional chaining (`state.data?.name`) entirely!

### 8. Under-the-Hood Internal Engine Flow
TypeScript's control flow analysis evaluates the discriminant property across each branch. If every member of the union is handled, the switch statement is type-safe and exhaustive.

### 9. When to Use It
State management for network API requests, modal dialogs, accessible forms, and reusable component libraries.

### 10. When NOT to Use It
Do not use complex discriminated unions for simple binary flags (e.g. `isOpen: boolean`).

### 11. Common Mistakes & Anti-Patterns
Using independent boolean flags like `{ isLoading: boolean, isError: boolean, data: T | null }`, which allows impossible states like `{ isLoading: true, isError: true }`.

### 12. Performance & Accessibility (A11y) Implications
Discriminated unions ensure that loading skeletons, error alerts, and success views are rendered with their corresponding ARIA roles cleanly separated.

### 13. Real-World Production Usage
Core state representation in Redux Toolkit, TanStack Query, and Stripe payment confirmation dialogs.

### 14. Common Interview Questions & Spoken Answers
**Q: Why is Discriminated Union preferred over multiple boolean flags for API state?**
**Spoken Answer:** Multiple boolean flags like `isLoading`, `isError`, and `isSuccess` allow impossible states—such as both `isLoading` and `isError` being true simultaneously. A discriminated union with a single `status` property (`idle | loading | success | error`) makes impossible states unrepresentable in the type system, ensuring that data is only accessible when `status === "success"`, completely preventing runtime null pointer crashes.

